				const obj = await env.BUCKET.put(filename, req.body, {
					httpMetadata: req.headers,
					ssecKey: SSEC_KEY,
				});
				const headers = new Headers();
				maybeObj.writeHttpMetadata(headers);
				return new Response(null, {
					headers,
					status: 201
				});
			}
			default: {
				return new Response("Method not allowed", {
					status: 405
				});
			}
		}
	}
}
```

